    "memory": [
        {
            "id": "0",
            "text": "Tokyo's urban landscape reflects the city's commitment to sustainability and creating livable spaces for residents",
            "event": "ADD"
        },
        {
            "id": "1",
            "text": "Tokyo has a compact city design, efficient public transportation, green spaces, and energy-efficient buildings",
            "event": "ADD"
        },
        {
            "id": "2",
            "text": "Tokyo's approach to sustainability shows that it is possible for a city to grow and develop while prioritizing the environment and the well-being of its residents",
            "event": "ADD"
        },
        {
            "id": "3",
            "text": "Many cities worldwide are taking steps towards sustainable development practices",
            "event": "ADD"
        },
        {
            "id": "4",
            "text": "Individuals can reduce energy consumption, reduce single-use plastic, practice environmentally friendly lifestyle choices, support sustainable practices, and educate themselves and others",
            "event": "ADD"
        },
        {
            "id": "5",
            "text": "Advocating for sustainable policies in the community involves educating the community, joining local advocacy groups, participating in local government meetings, writing to officials, and sharing ideas",
            "event": "ADD"
        }
    ]
}

